    private static func testRunningTimerRestoresDeadline(in directory: URL, recorder: inout Recorder) {
        let baseline = Date(timeIntervalSince1970: floor(Date().timeIntervalSince1970) - 30)
        var timer = TimerState(mode: .focus, duration: 120)
        timer.start(at: baseline)

        var preferences = Preferences()
        preferences.soundEnabled = false
        preferences.notificationsEnabled = false
        let archive = LocalArchive(timer: timer, sessions: [], preferences: preferences)

        do {
            try write(archive: archive, to: archiveURL(in: directory))
            let model = AppModel(dataDirectory: directory)
            let expectedDeadline = baseline.addingTimeInterval(120)

            recorder.check(model.timer.phase == .running, "running restore: timer remains running")
            recorder.check(
                approximately(model.timer.remaining(at: expectedDeadline.addingTimeInterval(-20)), 20),
                "running restore: remaining time derives from saved deadline"
            )
            model.advance(to: expectedDeadline.addingTimeInterval(1))
            recorder.check(model.sessions.count == 1, "running restore: elapsed saved timer records one session")
        } catch {
            recorder.fail("running restore: could not write or load archive: \(error)")
        }
    }

