    private static func testCorruptArchiveIsPreserved(in directory: URL, recorder: inout Recorder) {
        let original = Data("{this is not valid Still state".utf8)
        let stateURL = archiveURL(in: directory)

        do {
            try FileManager.default.createDirectory(at: stateURL.deletingLastPathComponent(), withIntermediateDirectories: true)
            try original.write(to: stateURL, options: .atomic)

            let model = AppModel(dataDirectory: directory)
            recorder.check(model.storageError != nil, "corrupt archive: reports a storage error")

            let contents = try FileManager.default.contentsOfDirectory(
                at: stateURL.deletingLastPathComponent(),
                includingPropertiesForKeys: nil
            )
            let backups = contents.filter { $0.lastPathComponent.hasPrefix("state-unreadable-") }
            recorder.check(backups.count == 1, "corrupt archive: creates one backup")
            if let backup = backups.first {
                recorder.check(try Data(contentsOf: backup) == original, "corrupt archive: backup preserves exact bytes")
            }
            recorder.check(try Data(contentsOf: stateURL) == original, "corrupt archive: original stays untouched")

            model.reset()
            model.persist()
            let repaired = try Data(contentsOf: stateURL)
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .iso8601
            _ = try decoder.decode(LocalArchive.self, from: repaired)
            recorder.check(repaired != original, "corrupt archive: successful backup permits a fresh state to be saved")
            if let backup = backups.first {
                recorder.check(try Data(contentsOf: backup) == original, "corrupt archive: backup stays immutable after recovery")
            }
        } catch {
            recorder.fail("corrupt archive: fixture failed: \(error)")
        }
    }

    private static func testFocusPresetDoesNotRestart(in directory: URL, recorder: inout Recorder) {
        let model = AppModel(dataDirectory: directory)
        prepareForTimerUse(model, focusMinutes: 25)

        model.startFocus(minutes: 50)
        let originalDeadline = model.timer.deadline
        let originalSessionID = model.timer.sessionID
        model.startFocus(minutes: 25)

        recorder.check(model.timer.phase == .running, "preset: 50-minute start begins focus")
        recorder.check(model.timer.mode == .focus, "preset: start remains in focus mode")
        recorder.check(model.timer.duration == 50 * 60, "preset: 50-minute duration is applied")
        recorder.check(model.timer.deadline == originalDeadline, "preset: start is ignored while timer is in progress")
        recorder.check(model.timer.sessionID == originalSessionID, "preset: in-progress start keeps session identity")
    }

    private static func testFocusPresetPreferences(in directory: URL, recorder: inout Recorder) {
        let defaults = Preferences()
        recorder.check(defaults.focusMinutes == 30, "preset preferences: default focus duration is 30 minutes")
        recorder.check(defaults.focusPresets == [30, 45, 60], "preset preferences: default slots are 30, 45, and 60 minutes")

        let maximumScale = Preferences(compactScale: 3.0)
        recorder.check(maximumScale.compactScale == 3.0, "compact scale: initializer preserves 3.0")
        recorder.check(Preferences(compactScale: 4.0).compactScale == 3.0, "compact scale: initializer clamps 4.0 to 3.0")

        do {
            let encoded = try JSONEncoder().encode(maximumScale)
            let encodedScale = try JSONSerialization.jsonObject(with: encoded) as? [String: Any]
            recorder.check(encodedScale?["compactScale"] as? Double == 3.0, "compact scale: encoding preserves 3.0")

            let decoded = try JSONDecoder().decode(Preferences.self, from: encoded)
            recorder.check(decoded.compactScale == 3.0, "compact scale: decoding preserves 3.0")
        } catch {
            recorder.fail("compact scale: preference round trip failed: \(error)")
        }

        let scalePersistenceDirectory = directory.appendingPathComponent("scale-persistence", isDirectory: true)
        let scaleModel = AppModel(dataDirectory: scalePersistenceDirectory)
        scaleModel.preferences.compactScale = 3.0
        scaleModel.savePreferences()
        let restoredScaleModel = AppModel(dataDirectory: scalePersistenceDirectory)
        recorder.check(restoredScaleModel.preferences.compactScale == 3.0, "compact scale: persistence preserves 3.0")

        let clamped = Preferences(focusPresets: [0, 500])
        recorder.check(clamped.focusPresets == [1, 180, 60], "preset preferences: short out-of-range arrays clamp and fill by slot")

        do {
            let encoded = try JSONEncoder().encode(Preferences(focusPresets: [37, 37, 120]))
            let decoded = try JSONDecoder().decode(Preferences.self, from: encoded)
            recorder.check(decoded.focusPresets == [37, 37, 120], "preset preferences: round trip preserves slot order and duplicates")
        } catch {
            recorder.fail("preset preferences: preference round trip failed: \(error)")
        }

        for (slot, minutes) in defaults.focusPresets.enumerated() {
            let presetModel = AppModel(dataDirectory: directory.appendingPathComponent("slot-\(slot)", isDirectory: true))
            presetModel.startFocus(minutes: minutes)
            recorder.check(
                presetModel.timer.duration == Double(minutes * 60),
                "preset preferences: slot \(slot + 1) starts a \(minutes)-minute focus timer"
            )
        }

        let model = AppModel(dataDirectory: directory.appendingPathComponent("persistence", isDirectory: true))
        model.preferences.focusPresets = [37, 37, 120]
        model.savePreferences()
        model.startFocus(minutes: 37)
        guard let originalDeadline = model.timer.deadline, let originalSessionID = model.timer.sessionID else {
            recorder.fail("preset preferences: persisted focus timer did not start")
            return
        }

        model.preferences.focusPresets = [40, 40, 120]
        model.savePreferences()

        recorder.check(model.timer.deadline == originalDeadline, "preset preferences: saving while active keeps the deadline")
        recorder.check(model.timer.sessionID == originalSessionID, "preset preferences: saving while active keeps the session identity")

        let restored = AppModel(dataDirectory: directory.appendingPathComponent("persistence", isDirectory: true))
        recorder.check(restored.preferences.focusPresets == [40, 40, 120], "preset preferences: saved slots restore in order with duplicates")
    }

    private static func testAppearancePreferences(in directory: URL, recorder: inout Recorder) {
        let defaults = Preferences()
        recorder.check(defaults.colorTheme == "sage", "appearance preferences: default color theme is sage")
        recorder.check(defaults.edgeStyle == "glass", "appearance preferences: default edge style is glass")

        var normalized = Preferences(colorTheme: "OCEAN", edgeStyle: "DIFFUSE")
        recorder.check(normalized.colorTheme == "ocean", "appearance preferences: initializer lowercases color theme")
        recorder.check(normalized.edgeStyle == "diffuse", "appearance preferences: initializer lowercases edge style")
        normalized.colorTheme = "unknown"
        normalized.edgeStyle = "blurred"
        normalized.sanitize()
        recorder.check(normalized.colorTheme == "sage", "appearance preferences: invalid color theme falls back to sage")
        recorder.check(normalized.edgeStyle == "glass", "appearance preferences: invalid edge style falls back to glass")

        let colorThemes = ["sage", "ocean", "lavender", "rose", "sand", "clay", "graphite", "mint"]
        for colorTheme in colorThemes {
            do {
                let encoded = try JSONEncoder().encode(Preferences(colorTheme: colorTheme))
                let decoded = try JSONDecoder().decode(Preferences.self, from: encoded)
                recorder.check(decoded.colorTheme == colorTheme, "appearance preferences: \(colorTheme) survives a round trip")
            } catch {
                recorder.fail("appearance preferences: \(colorTheme) round trip failed: \(error)")
            }
        }

        let model = AppModel(dataDirectory: directory.appendingPathComponent("persistence", isDirectory: true))
        prepareForTimerUse(model, focusMinutes: 37)
        model.preferences.edgeStyle = "DIFFUSE"
        model.startFocus(minutes: 37)
        guard let deadline = model.timer.deadline, let sessionID = model.timer.sessionID else {
            recorder.fail("appearance preferences: focus timer did not start")
            return
        }
        model.savePreferences()
        recorder.check(model.timer.deadline == deadline, "appearance preferences: saving preserves a running deadline")
        recorder.check(model.timer.sessionID == sessionID, "appearance preferences: saving preserves a running session identity")

        let restored = AppModel(dataDirectory: directory.appendingPathComponent("persistence", isDirectory: true))
        recorder.check(restored.preferences.edgeStyle == "diffuse", "appearance preferences: diffuse edge style restores")
        // Recovery archives store ISO-8601 timestamps at whole-second precision.
        let archivedDeadline = Date(timeIntervalSince1970: floor(deadline.timeIntervalSince1970))
        recorder.check(restored.timer.deadline == archivedDeadline, "appearance preferences: persisted timer deadline restores")
        recorder.check(restored.timer.sessionID == sessionID, "appearance preferences: persisted timer session identity restores")
    }

    private static func testJournalPathAppendAndRestore(in directory: URL, recorder: inout Recorder) {
        let stateDirectory = directory.appendingPathComponent("state", isDirectory: true)
        let journalURL = directory.appendingPathComponent("sessions.md")
        let model = AppModel(dataDirectory: stateDirectory)
        prepareForTimerUse(model, focusMinutes: 1)

        var pathSaved: Bool?
        Task { pathSaved = await model.setJournalPathAsync(journalURL.path) }
        recorder.check(waitUntil { pathSaved != nil } && pathSaved == true, "journal: async path selection accepts a writable Markdown file")
        model.startFocus(minutes: 1)
        guard let startedAt = model.timer.startedAt else {
            recorder.fail("journal: focus timer did not start")
            return
        }
        model.advance(to: startedAt.addingTimeInterval(61))
        recorder.check(waitForJournal(model), "journal: completion finishes its background write")

        do {
            let written = try MarkdownJournal.read(from: journalURL)
            recorder.check(model.sessions.count == 1, "journal: completed focus remains in local archive")
            recorder.check(written.count == 1, "journal: completed focus appends one Markdown row")
            recorder.check(written.first?.id == model.sessions.first?.id, "journal: Markdown row has local session identity")

            let restored = AppModel(dataDirectory: stateDirectory)
            recorder.check(waitForJournal(restored), "journal: restore finishes before synchronous CLI path change")
            recorder.check(restored.sessions.count == 1, "journal: local archive restores one session")
            recorder.check(try MarkdownJournal.read(from: journalURL).count == 1, "journal: restore does not duplicate Markdown rows")
            recorder.check(restored.setJournalPath(journalURL.path), "journal: resetting the same path succeeds")
            recorder.check(try MarkdownJournal.read(from: journalURL).count == 1, "journal: resetting the path remains idempotent")
        } catch {
            recorder.fail("journal: could not read persisted Markdown: \(error)")
        }
    }

